CREATE OR REPLACE FUNCTION private.is_active_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select exists(select 1 from public.user_profiles p where p.id=(select auth.uid()) and p.active) $function$
CREATE OR REPLACE FUNCTION private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select exists(select 1 from public.user_profiles p where p.id=(select auth.uid()) and p.active and p.role='admin') $function$
CREATE OR REPLACE FUNCTION public.mark_prepared_used()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
  if coalesce(new.action,'') like '%ยืม%' and new.equipment_name is not null and new.equipment_number is not null then
    update public.prepare_records set status='ยืมแล้ว'
    where status='เตรียม' and equipment_type=new.equipment_name and equipment_number=new.equipment_number;
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION private.borrow_records_backdate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bkk_now timestamp := now() at time zone 'Asia/Bangkok';
begin
  if (select auth.uid()) is null or private.is_admin() then return new; end if;
  if coalesce(new.action, '') !~ '(ยืม|คืน|ย้าย)' then return new; end if;

  if tg_op = 'INSERT' then
    if new.recorded_at is null or abs(extract(epoch from (new.recorded_at - now()))) > 900 then
      new.recorded_at := now();
      new.record_date := bkk_now::date;
      new.record_time := bkk_now::time(0);
    end if;
  elsif new.record_date is distinct from old.record_date
     or (new.recorded_at at time zone 'Asia/Bangkok')::date is distinct from (old.recorded_at at time zone 'Asia/Bangkok')::date then
    raise exception 'แก้วันที่ของรายการยืม-คืนได้เฉพาะแอดมิน' using errcode = '42501';
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION private.borrow_records_registry_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  num_text text := btrim(coalesce(new.equipment_number, ''));
  num_int int := case when btrim(coalesce(new.equipment_number, '')) ~ '^[0-9]+$' then btrim(new.equipment_number)::int end;
  reg_status text;
begin
  if coalesce(new.action, '') !~ 'ยืม' then return new; end if;
  if new.equipment_name is null or not exists (select 1 from public.assets a where a.type = new.equipment_name) then
    return new;
  end if;

  -- เลขซ้ำในทะเบียน: ถ้ามีแถวไหน "ใช้งานได้" ถือว่าใช้ได้ (ตรงกับหน้าเว็บ)
  select coalesce(max(case when coalesce(a.status, 'ใช้งานได้') = 'ใช้งานได้' then 'ใช้งานได้' end), max(a.status))
    into reg_status
    from public.assets a
   where a.type = new.equipment_name and num_int is not null and a.no = num_int;

  if reg_status is null then
    raise exception '% No.% ไม่มีในทะเบียนครุภัณฑ์ — เพิ่มในทะเบียนก่อนจึงจะยืมได้', new.equipment_name, num_text;
  elsif reg_status <> 'ใช้งานได้' then
    raise exception '% No.% สถานะในทะเบียนคือ "%" — ยืมไม่ได้', new.equipment_name, num_text, reg_status;
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION private.audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end;
  n jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end;
  diff text[];
begin
  if tg_op = 'UPDATE' then
    select array_agg(k order by k) into diff
      from jsonb_object_keys(n) k
     where k not in ('updated_at') and (o -> k) is distinct from (n -> k);
    if diff is null then return null; end if;   -- แก้แล้วค่าเหมือนเดิม ไม่ต้องบันทึก
  end if;
  insert into public.audit_log (actor_user_id, table_name, action, row_id, old_data, new_data, changed)
  values ((select auth.uid()), tg_table_name, lower(tg_op), coalesce(n ->> 'id', o ->> 'id'), o, n, diff);
  return null;
end $function$
